#include <vector>
#include <string>
#include <unordered_map>
#include <sstream>

using namespace std;

class Solution {
public:
    vector<vector<string>> findDuplicate(vector<string>& paths) {
        unordered_map<string, vector<string>> contentMap;

        for (string& path : paths) {
            stringstream ss(path);
            string dir, file;
            ss >> dir;

            while (ss >> file) {
                int idx = file.find('(');
                string name = file.substr(0, idx);
                string content = file.substr(idx + 1, file.size() - idx - 2);
                contentMap[content].push_back(dir + "/" + name);
            }
        }

        vector<vector<string>> res;
        for (auto& [content, files] : contentMap)
            if (files.size() > 1)
                res.push_back(files);

        return res;
    }
};
